head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.nPreRow = -1;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_3);
    await scwin.ins_Search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_CntrInfo_OnLoadError
 * @description dts_CntrInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_CntrInfo_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_CntrInfo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.dts_CntrInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_CntrInfo_OnLoadCompleted
 * @description dts_CntrInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_CntrInfo_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_CntrInfo.errorMsg) {
            await $c.win.alert(dts_CntrInfo.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }

        // 데이터가 없는 경우
        if (rowcount === 0) {
            fn_CtrlBtn_temp("no_data");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.dts_CntrInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_CntrInfo_OnRowPosChanged
 * @description Cntr Info On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_CntrInfo_OnRowPosChanged = async function(row) {
    try {
        // 조회된 것들은 국가코드 비활성, 신규로 생성된 것만 활성.
        if (dts_CntrInfo.getCellData(row, "CNTR_CD") !== "") {
            await scwin.ins_SearchDetail();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.dts_CntrInfo_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_FornInst_OnLoadError
 * @description dts_FornInst 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_FornInst_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_FornInst);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.dts_FornInst_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_FornInst_OnRowPosChanged
 * @description Forn Inst On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_FornInst_OnRowPosChanged = function(row) {
    try {
        if (row <= 0) {
            return;
        }
        dts_FornInst.undoRow(scwin.nPreRow);
        scwin.nPreRow = row;
        if (dts_FornInst.getCellData(row, "SELECTED") === "Y") {
            fn_CtrlBtn_temp("update");
        } else {
            fn_CtrlBtn_temp("insert");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS05300.dts_FornInst_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_FornInst_OnLoadCompleted
 * @description dts_FornInst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_FornInst_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_FornInst.errorMsg) {
            await $c.win.alert(dts_FornInst.errorMsg);
        } else {
            txb_TotalCnt2.setValue("총 " + rowcount + "건");
        }

        // 데이터가 없는 경우
        if (rowcount === 0) {
            fn_CtrlBtn_temp("no_data");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.dts_FornInst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.ins_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.btn_search_onclick" });
    }
};

/**
 * @method
 * @name btn_search2_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search2_onclick = async function() {
    try {
        await scwin.ins_SearchDetail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.btn_search2_onclick" });
    }
};

/**
 * @method
 * @name btn_new_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_new_onclick = function() {
    try {
        scwin.new();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS05300.btn_new_onclick" });
    }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function() {
    try {
        await scwin.ins_Update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.btn_modify_onclick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.ins_Insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.btn_save_onclick" });
    }
};

/**
 * @method
 * @name txb_CNTR_NM_onkeydown
 * @description txb_CNTR_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_CNTR_NM_onkeydown = async function() {
    try {
        fn_DelChar(this);
        if (event.keyCode === 13) {
            await scwin.ins_Search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.txb_CNTR_NM_onkeydown" });
    }
};

/**
 * @method
 * @name txb_FORN_INST_NM1_onkeydown
 * @description txb_FORN_INST_NM1 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_FORN_INST_NM1_onkeydown = async function() {
    try {
        fn_DelChar(this);
        if (event.keyCode === 13) {
            await scwin.ins_SearchDetail();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.txb_FORN_INST_NM1_onkeydown" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        alert_tr_error(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS05300.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        // alert( getMessageParam("MSG-A001", "저장") );
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));

        // 재조회
        await scwin.ins_SearchDetail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Delete_OnFail
 * @description Delete On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Delete_OnFail = function() {
    try {
        alert_tr_error(trs_Delete);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS05300.trs_Delete_OnFail" });
    }
};

/**
 * @method
 * @name trs_Delete_OnSuccess
 * @description Delete On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnSuccess = async function() {
    try {
        // alert( getMessageParam("MSG-A001", "삭제") );
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));

        // 재조회
        await scwin.ins_SearchDetail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05300.trs_Delete_OnSuccess" });
    }
};

/**
 * @method
 * @name txb_CNTR_NM_onkeyup
 * @description txb_CNTR_NM 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_CNTR_NM_onkeyup = function() {
    try {
        fn_DelChar(this);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS05300.txb_CNTR_NM_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_Search
 * @description 국가코드조회 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Search = async function() {
    // 데이터셋 초기화
    scwin.initDs("select");
    txb_label.setValue("");

    // 조회조건 체크.
    if (!await scwin.chkValid("select")) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_CntrInfo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_CntrInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_SearchDetail
 * @description 외국기관 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_SearchDetail = async function() {
    // 데이터셋 초기화
    scwin.initDs("select_detail");

    // 조회조건 체크.
    if (!await scwin.chkValid("select_detail")) {
        return;
    }
    const CNTR_CD3 = dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "CNTR_CD3");
    txb_label.setValue(CNTR_CD3);

    // Lodaing~~~ 표시
    const nRow = dts_CntrInfo.getRowPosition();
    const sbmOptions = {
        id : "sbm_dts_FornInst",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_FornInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_Update
 * @description 외국기관 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Update = async function() {
    // 사전체크
    if (!await scwin.chkValid("update")) {
        return;
    }
    if (!confirm("수정하시겠습니까?")) {
        return;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/OrgInfoAction.do",
        ref : "dts_FornInst",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_Insert
 * @description 외국기관 입력
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Insert = async function() {
    // 사전체크
    if (!await scwin.chkValid("insert")) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/OrgInfoAction.do",
        ref : "dts_FornInst",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @param {*} pFg pFg
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function(pFg) {
    if (pFg === "select") {
        dts_CntrInfo.removeAll();
        dts_FornInst.removeAll();
    } else if (pFg === "select_detail") {
        dts_FornInst.removeAll();
    }
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === undefined || pGubun === "select" || pGubun === "select_detail") {
        return true;
    }
    if (txb_FORN_INST_NM.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "외국기관명"));
        txb_FORN_INST_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_FORN_INST_NM, 60, "외국기관명")) {
        // txb_COM_ENG_NM.value = "";
        txb_FORN_INST_NM.focus();
        return false;
    }
    if (cmb_ACTIV_YN.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "활성여부"));
        cmb_ACTIV_YN.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name new
 * @description 신규버튼 클릭
 * @returns {void}
 * @hidden N
 */
scwin.new = function() {
    if (dts_FornInst.getRowCount() === 0) {
        scwin.nPreRow = -1;
    }
    dts_FornInst.insertRow();
    txb_CNTR_CD.setValue(dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "CNTR_CD"));
    cmb_ACTIV_YN.setSelectedIndex(0);
    txb_FORN_INST_NM.focus();
};
